const data = $json;

/**
 * Convierte changed_fields en un arreglo,
 * independientemente de cómo lo entregue PostgreSQL.
 */
function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value.map((item) => String(item));
  }

  if (typeof value === 'string' && value.trim() !== '') {
    try {
      const parsed = JSON.parse(value);

      if (Array.isArray(parsed)) {
        return parsed.map((item) => String(item));
      }
    } catch {
      return value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean);
    }
  }

  return [];
}

const changedFields = normalizeArray(data.changed_fields);

const budgetFields = new Set([
  'precio_base',
  'valor_total_adjudicacion',
]);

const statusFields = new Set([
  'fase',
  'estado_del_procedimiento',
  'id_estado_del_procedimiento',
  'estado_de_apertura_del_proceso',
  'estado_resumen',
]);

const dateFields = new Set([
  'fecha_de_publicacion_del',
  'fecha_de_ultima_publicaci',
  'fecha_de_publicacion_fase_3',
]);

const awardFields = new Set([
  'adjudicado',
  'id_adjudicacion',
  'codigoproveedor',
  'departamento_proveedor',
  'ciudad_proveedor',
  'valor_total_adjudicacion',
  'nombre_del_proveedor_adjudicado',
  'nit_del_proveedor_adjudicado',
]);

const categories = new Set();

for (const field of changedFields) {
  if (budgetFields.has(field)) {
    categories.add('budget');
  }

  if (statusFields.has(field)) {
    categories.add('status');
  }

  if (dateFields.has(field)) {
    categories.add('date');
  }

  if (awardFields.has(field)) {
    categories.add('award');
  }
}

const categoryList = [...categories];

let eventType = 'other';

if (categoryList.length > 1) {
  eventType = 'multiple_changes';
} else if (categories.has('award')) {
  eventType = 'award_changed';
} else if (categories.has('budget')) {
  eventType = 'budget_changed';
} else if (categories.has('status')) {
  eventType = 'status_changed';
} else if (categories.has('date')) {
  eventType = 'date_changed';
}

/**
 * Relevancia inicial basada en reglas.
 * Más adelante la IA podrá enriquecer esta clasificación.
 */
let relevanceLevel = 'low';

if (categories.has('award')) {
  relevanceLevel = 'critical';
} else if (
  categories.has('budget') ||
  categories.has('status') ||
  categories.has('date')
) {
  relevanceLevel = 'high';
} else if (changedFields.length >= 5) {
  relevanceLevel = 'medium';
}

const previousSnapshot =
  data.previous_snapshot &&
  typeof data.previous_snapshot === 'object'
    ? data.previous_snapshot
    : {};

const currentSnapshot =
  data.current_snapshot &&
  typeof data.current_snapshot === 'object'
    ? data.current_snapshot
    : {};

const previousRaw =
  previousSnapshot.raw_json &&
  typeof previousSnapshot.raw_json === 'object'
    ? previousSnapshot.raw_json
    : {};

const currentRaw =
  currentSnapshot.raw_json &&
  typeof currentSnapshot.raw_json === 'object'
    ? currentSnapshot.raw_json
    : {};

/**
 * Conserva los valores anteriores y nuevos
 * únicamente para los campos que cambiaron.
 */
const rawChanges = {};

for (const field of changedFields) {
  rawChanges[field] = {
    before:
      previousRaw[field] !== undefined
        ? previousRaw[field]
        : null,

    after:
      currentRaw[field] !== undefined
        ? currentRaw[field]
        : null,
  };
}

const importantNormalizedFields = [
  'base_price',
  'process_status',
  'opening_status',
  'awarded',
  'total_awarded_value',
  'publication_date',
  'source_updated_at',
  'procurement_method',
  'contract_type',
];

const normalizedBefore = {};
const normalizedAfter = {};

for (const field of importantNormalizedFields) {
  normalizedBefore[field] =
    previousSnapshot[field] !== undefined
      ? previousSnapshot[field]
      : null;

  normalizedAfter[field] =
    currentSnapshot[field] !== undefined
      ? currentSnapshot[field]
      : null;
}

return {
  json: {
    version_id: data.version_id,
    process_id: data.process_id,
    secop_process_id: data.secop_process_id,
    version_number: Number(data.version_number),

    event_type: eventType,
    relevance_level: relevanceLevel,

    changed_fields: changedFields,

    change_summary: {
      changed_count: changedFields.length,
      categories: categoryList,
      raw_changes: rawChanges,
      normalized_before: normalizedBefore,
      normalized_after: normalizedAfter,
    },

    status: 'pending',

    source_updated_at:
      data.source_updated_at || null,

    metadata: {
      reference: data.reference || null,
      entity_name: data.entity_name || null,
      entity_nit: data.entity_nit || null,
      department: data.department || null,
      city: data.city || null,
      process_name: data.process_name || null,
      process_url: data.process_url || null,

      captured_at: data.captured_at || null,

      classification_method: 'deterministic_rules',
      classification_version: 'rules_v1',
    },
  },
};

const items = $('Leer versiones pendientes')
  .all(0, $runIndex)
  .filter((item) => item.json.version_id);

// La consulta PostgreSQL ya entrega las versiones ordenadas.
// Por eso tomamos directamente la última del lote.
if (items.length === 0) {
  return [];
}

const lastItem = items[items.length - 1].json;

return [
  {
    json: {
      source_code: 'SECOP_II_PROCESS_VERSIONS',

      // Enviamos solamente el UUID.
      // PostgreSQL recuperará la fecha exacta con microsegundos.
      cursor_version_id: String(lastItem.version_id),

      batch_count: items.length,
    },
  },
];
